fn main() {
    let age = 30;        // `age` est immuable par défaut
    println!("{age}");   // affiche : 30

    // age = 31;         // ERREUR : cannot assign twice to immutable variable
}

fn main() {
    let mut compteur = 0; // `mut` autorise la modification
    compteur = compteur + 1;
    compteur += 1;        // `+=` ajoute en place
    println!("{compteur}"); // affiche : 2
}

fn main() {
    let saisie = "42";              // ici `saisie` est un texte (&str)
    let saisie: i32 = saisie.trim().parse().unwrap(); // nouveau `saisie`, de type i32
    let saisie = saisie * 2;        // encore un nouveau `saisie` : 84
    println!("{saisie}");           // affiche : 84
}

const SECONDES_PAR_HEURE: u32 = 60 * 60; // type obligatoire, calcul connu à la compilation

fn main() {
    println!("Une heure vaut {SECONDES_PAR_HEURE} secondes"); // affiche : 3600
}

fn main() {
    let petit: u8 = 255;       // non signé 8 bits : 0 à 255
    let temperature: i32 = -7; // signé : accepte le négatif
    let grand: u64 = 10_000_000_000; // `_` sert juste à la lisibilité
    println!("{petit} {temperature} {grand}");
}

fn main() {
    let pi = 3.14159;        // inféré en f64 (flottant par défaut)
    let majeur: bool = true; // un booléen
    let initiale = 'A';      // un char (apostrophes simples)
    let symbole = '€';       // char Unicode, pas seulement ASCII
    println!("{pi} {majeur} {initiale} {symbole}");
}

fn main() {
    let devine = 5;          // inféré : i32
    let precis: i64 = 5;     // annotation explicite : i64
    let grand = 5i64;        // autre façon : suffixe de type collé au nombre

    // Ici l'annotation est nécessaire pour que `parse` sache quoi produire :
    let nombre: u32 = "10".parse().unwrap();
    println!("{devine} {precis} {grand} {nombre}");
}

sections.solution:
Un âge est petit et jamais négatif, donc un entier non signé comme `u8` (0 à 255) suffit. Une température avec décimales et signe possible demande un flottant `f64`. Une information vrai/faux est un `bool`. Une lettre unique est un `char`.

```rust
fn main() {
    let age: u8 = 30;              // non signé, petit
    let temperature: f64 = -3.5;   // flottant, négatif possible
    let conditions_validees: bool = true; // booléen
    let initiale: char = 'C';      // un seul caractère Unicode
    println!("{age} {temperature} {conditions_validees} {initiale}");
}
```
